// Dispatch status API -- serves the family-private live readout PWA at
// /dispatch-status. ONE GET webhook (path 'dispatch-status') branches on the
// ?section= query param:
//   section=reel  -> last 50 entries of /data/poetech-briefing/_reel.jsonl,
//                    newest-first, returned as a JSON array. Missing file =>
//                    empty array (NOT an error).
//   section=tasks -> /data/poetech-briefing/_dispatch_state.json verbatim.
//                    Missing file => { snapshot_at: null, tasks: [] }.
//
// The orchestrator writes both files (the reel via the continuous-feedback-reel
// flow; _dispatch_state.json via a separate tasks-feed flow). This endpoint is
// read-only and never throws on missing input.
//
// Returns a single item { json: { payload } }; the Respond node serializes
// $json.payload directly so the HTTP body is the raw array (reel) or object
// (tasks).

const fs = require('fs');

const BRIEFING_DIR = '/data/poetech-briefing';
const REEL_FILE = BRIEFING_DIR + '/_reel.jsonl';
const STATE_FILE = BRIEFING_DIR + '/_dispatch_state.json';
const MAX_ENTRIES = 50;

const input = $input.first().json || {};
const query = (input.query && typeof input.query === 'object') ? input.query : {};
const section = String(query.section || 'reel').toLowerCase();

function readReel() {
  let raw;
  try {
    raw = fs.readFileSync(REEL_FILE, 'utf8');
  } catch (e) {
    return []; // Missing file is the normal cold-start state.
  }
  const lines = raw.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  // Newest-first: reel is append-only (oldest first on disk), so take the tail
  // then reverse.
  const tail = lines.slice(-MAX_ENTRIES).reverse();
  const out = [];
  for (const line of tail) {
    try { out.push(JSON.parse(line)); }
    catch (e) { out.push({ ts: null, type: 'parse-error', summary: line.slice(0, 200) }); }
  }
  return out;
}

function readTasks() {
  try {
    const parsed = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
    if (parsed && typeof parsed === 'object') {
      if (!Array.isArray(parsed.tasks)) parsed.tasks = [];
      if (parsed.snapshot_at === undefined) parsed.snapshot_at = null;
      return parsed;
    }
    return { snapshot_at: null, tasks: [] };
  } catch (e) {
    return { snapshot_at: null, tasks: [] };
  }
}

let payload;
if (section === 'tasks') payload = readTasks();
else payload = readReel();

return [{ json: { payload } }];
